begin;
create temporary table gerot_original on commit drop as select month,payload from public.efc_workbook_history where month between '2026-01' and '2026-09';
with targets(month,efc,resupply,replenishment,efm,wms) as (values ('2026-01',0.9754,0.0347,0.1209,0.9309000000000001,0.914),('2026-02',0.9645999999999999,0.038900000000000004,0.11779999999999999,0.9255,0.9),('2026-03',0.9649,0.0318,0.1093,0.9423999999999999,0.8778),('2026-04',0.9678,0.0524,0.12359999999999999,0.8782,0.9517),('2026-05',0.9743999999999999,0.0262,0.1065,0.89,0.9246),('2026-06',0.9787,0.0253,0.1166,0.971,0.9),('2026-07',0.9984000000000001,0.0253,0.09820000000000001,0.9804,0.9499),('2026-08',1,0.024300000000000002,0.09759999999999999,0.9819,0.9537),('2026-09',0.9704,0.029500000000000002,0.1185,0.9727,0.9621999999999999))
update public.efc_workbook_history h set payload=jsonb_set(h.payload,'{manual_results}',jsonb_build_object('source','GEROT – GERAL / image(20261007-103355).png','entered_at','2026-10-07','mode','manual_monthly_closure','daily_wms_method','weighted_residual_for_pending_days','efc',t.efc,'resupply_rate',t.resupply,'replenishment_rate',t.replenishment,'efm',t.efm,'wms',t.wms)) from targets t where h.month=t.month;
do $$begin if (select count(*) from gerot_original)<>9 then raise exception 'Missing monthly history'; end if; if exists(select 1 from gerot_original a join public.efc_workbook_history b using(month) where a.payload-'manual_results' is distinct from b.payload-'manual_results') then raise exception 'Underlying historical records changed';end if;end$$;
select month,payload->'manual_results' as manual_results from public.efc_workbook_history where month between '2026-01' and '2026-09' order by month;
commit;
